        try: r=json.loads(r)
        except: return r
    if isinstance(r,list): r=r[0]
    cc=r.get('content')
    if isinstance(cc,dict):
        return cc.get('source',{}).get('data',str(cc))
    return str(cc) if cc else str(r)
